(function () {
window.dataLayer = window.dataLayer || [];
document.addEventListener('click', function (e) {
var t = e.target.closest('[data-ev]');
if (!t) return;
if (t.hasAttribute('data-wa-trigger') && document.querySelector('[data-wa-menu].is-open')) return;
window.dataLayer.push({ event: t.dataset.ev, ev_loc: t.dataset.evLoc || '', page_path: location.pathname, wa_option: t.dataset.waOpen || t.dataset.waOption || '' });
}, true);
var ID = (document.documentElement.getAttribute('data-analytics-id') || '').trim();
if (ID) {
var s = document.createElement('script');
s.async = true;
if (ID.indexOf('GTM-') === 0) {
window.dataLayer.push({ 'gtm.start': Date.now(), event: 'gtm.js' });
s.src = 'https://www.googletagmanager.com/gtm.js?id=' + encodeURIComponent(ID);
} else {
window.gtag = function () { window.dataLayer.push(arguments); };
window.gtag('js', new Date());
window.gtag('config', ID, { anonymize_ip: true });
s.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(ID);
}
document.head.appendChild(s);
}
var contactForm = document.querySelector('form[action="/lead-forward.php"]');
if (/^\/contacto(?:\/|\/index\.html)?$/.test(location.pathname) && contactForm) {
var error = new URLSearchParams(location.search).get('error');
if (error === 'telefono' || error === 'envio') {
var alert = document.createElement('p');
alert.setAttribute('role', 'alert');
alert.textContent = error === 'telefono'
? 'Revisá el número: ingresá tu WhatsApp completo, de 6 a 15 dígitos. Podés usar +595, espacios o guiones.'
: 'No pudimos enviar tus datos. Escribinos por WhatsApp para coordinar tu tasación: ';
if (error === 'envio') {
var link = document.createElement('a');
link.href = contactForm.getAttribute('data-wa-error') || '/contacto/';
link.textContent = 'Escribinos por WhatsApp';
alert.appendChild(link);
}
contactForm.before(alert);
}
}
var gws = document.querySelectorAll('[data-gracias-wa]');
if (gws.length) {
var gp = null;
try { gp = new URLSearchParams(location.search).get('p'); } catch (err) {  }
Array.prototype.forEach.call(gws, function (gw) {
try {
var gmap = JSON.parse(gw.getAttribute('data-wa-map') || '{}');
if (gp && Object.prototype.hasOwnProperty.call(gmap, gp)) gw.href = gmap[gp];
} catch (err) {  }
});
var gpl = document.querySelector('[data-gracias-purpose]');
if (gpl && gp) {
try {
var labels = JSON.parse(gpl.getAttribute('data-labels') || '{}');
if (Object.prototype.hasOwnProperty.call(labels, gp)) {
gpl.textContent = 'Tu consulta: ' + labels[gp];
gpl.hidden = false;
}
} catch (err) {  }
}
}
var submissionId = document.getElementById('submission_id');
if (submissionId && window.crypto && window.crypto.getRandomValues) {
var bytes = new Uint8Array(16);
window.crypto.getRandomValues(bytes);
submissionId.value = Array.prototype.map.call(bytes, function (b) { return ('0' + b.toString(16)).slice(-2); }).join('');
}
if (contactForm) {
contactForm.addEventListener('submit', function () {
var purpose = contactForm.querySelector('[name="purpose"]');
window.dataLayer.push({ event: 'form_submit', ev_loc: 'contact_form', page_path: location.pathname, wa_option: purpose ? purpose.value : '' });
});
}
var formTs = document.getElementById('form_ts');
if (formTs && formTs.form) {
var formLoaded = Date.now();
formTs.form.addEventListener('submit', function () { formTs.value = String(Date.now() - formLoaded); });
}
var pu = document.getElementById('page_url');
if (pu) pu.value = location.href;
var yr = document.getElementById('yr');
if (yr) yr.textContent = new Date().getFullYear();
var hdr = document.querySelector('[data-hdr]');
if (hdr) {
var onScroll = function () {
hdr.classList.toggle('is-stuck', window.scrollY > 8);
};
onScroll();
document.addEventListener('scroll', onScroll, { passive: true });
var burger = document.querySelector('[data-hdr-burger]');
var panel = document.querySelector('[data-hdr-panel]');
if (burger && panel) {
var setNav = function (open, returnFocus) {
panel.classList.toggle('is-open', open);
burger.setAttribute('aria-expanded', open ? 'true' : 'false');
if (!open && returnFocus) burger.focus();
};
burger.addEventListener('click', function () {
setNav(!panel.classList.contains('is-open'), false);
});
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape' && panel.classList.contains('is-open')) setNav(false, true);
});
document.addEventListener('click', function (e) {
if (!panel.classList.contains('is-open')) return;
if (panel.contains(e.target) || burger.contains(e.target)) return;
setNav(false, false);
});
}
}
var mbar = document.querySelector('[data-mbar]');
var heroCta = document.querySelector('[data-ev-loc="hero"]');
if (mbar && heroCta && 'IntersectionObserver' in window) {
var mbarIO = new IntersectionObserver(function (entries) {
mbar.classList.toggle('is-hidden', entries[entries.length - 1].isIntersecting);
});
mbarIO.observe(heroCta);
}
var menu = document.querySelector('[data-wa-menu]');
var triggers = Array.prototype.slice.call(document.querySelectorAll('[data-wa-trigger]'));
if (menu && triggers.length) {
var panelEl = menu.querySelector('[data-wa-panel]');
var options = Array.prototype.slice.call(menu.querySelectorAll('.wa-menu__option'));
var lastTrigger = null;
var hideTimer = null;
var supportsInert = 'inert' in HTMLElement.prototype;
var background = Array.prototype.slice.call(document.querySelectorAll('body > header, body > main, body > footer'));
function isOpen() { return menu.classList.contains('is-open'); }
function setBackground(locked) {
document.body.classList.toggle('is-locked', locked);
if (supportsInert) background.forEach(function (el) { el.inert = locked; });
}
function open(trigger) {
lastTrigger = trigger || null;
window.clearTimeout(hideTimer);
hideTimer = null;
setBackground(true);
var anchor = (trigger && trigger.dataset.waAnchor) || 'fab';
panelEl.setAttribute('data-anchor', anchor);
menu.hidden = false;
requestAnimationFrame(function () { menu.classList.add('is-open'); });
triggers.forEach(function (t) { t.setAttribute('aria-expanded', t === trigger ? 'true' : 'false'); });
var wantId = trigger && trigger.dataset.waOpen;
var target = (wantId && options.filter(function (o) { return o.dataset.waOption === wantId; })[0]) || options[0];
options.forEach(function (o) { o.classList.toggle('wa-menu__option--current', o === target); });
if (target) target.focus();
}
function close(returnFocus) {
if (!isOpen()) { menu.hidden = true; return; }
menu.classList.remove('is-open');
triggers.forEach(function (t) { t.setAttribute('aria-expanded', 'false'); });
setBackground(false);
window.clearTimeout(hideTimer);
hideTimer = window.setTimeout(function () { hideTimer = null; if (!isOpen()) menu.hidden = true; }, 200);
if (returnFocus && lastTrigger) lastTrigger.focus();
lastTrigger = null;
}
triggers.forEach(function (trigger) {
trigger.addEventListener('click', function (e) {
e.preventDefault();
if (isOpen()) { close(true); } else { open(trigger); }
});
});
menu.querySelectorAll('[data-wa-close]').forEach(function (closer) {
closer.addEventListener('click', function (e) { e.preventDefault(); close(true); });
});
options.forEach(function (option) {
option.addEventListener('click', function () { close(false); });
});
document.addEventListener('click', function (e) {
if (!isOpen()) return;
if (panelEl && panelEl.contains(e.target)) return;
if (triggers.some(function (t) { return t.contains(e.target); })) return;
close(false);
});
document.addEventListener('keydown', function (e) {
if (!isOpen()) return;
if (e.key === 'Escape') { close(true); return; }
if (e.key !== 'Tab') return;
var focusable = Array.prototype.slice.call(
menu.querySelectorAll('.wa-menu__option, [data-wa-close]:not([aria-hidden="true"])')
);
if (!focusable.length) return;
var first = focusable[0];
var last = focusable[focusable.length - 1];
if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
});
}
})();
